+					activeRun.generation = {
+						spanId: createId(),
+						startedAt: at,
+						model: readModel(),
+					};
+				}
+				break;
+
+			case "message_start":
+				if (activeRun && isAssistantMessage(event.message)) {
+					activeRun.generation ??= {
+						spanId: createId(),
+						startedAt: at,
+						model: modelFromMessage(event.message, activeRun.model),
