+
+			case "turn_end":
+				if (activeRun?.generation && isAssistantMessage(event.message)) {
+					finishGeneration(activeRun, event.message, at);
+				}
+				break;
+
+			case "tool_execution_start":
+				if (activeRun) {
+					activeRun.tools.set(event.toolCallId, {
+						startedAt: at,
+						toolName: event.toolName,
+					});
