+						success: !event.isError,
+						status: event.isError ? "error" : "success",
+					});
+				}
+				break;
+
+			case "agent_end":
+				if (activeRun) {
+					if (signal.aborted && activeRun.status === "success") {
+						activeRun.status = "aborted";
+						activeRun.errorCategory = "aborted";
