+					}
+					activeRun.generation = undefined;
+					activeRun.tools.clear();
+					activeRun = undefined;
+				}
+				break;
+		}
+	};
+
+	const unsubscribe = agent.subscribe(listener);
+	return () => {
+		if (disposed) return;
+		disposed = true;
+		unsubscribe();
+		activeRun?.tools.clear();
+		activeRun = undefined;
+	};
+}
